258	/** Claims name the quote step that created the policy they are settled against. */
259	const policyAt = (policies: Map<number, Policy>, step: number): Policy => {
260	  const policy = policies.get(step);
261	  if (policy === undefined) throw new Error(`No policy at step ${step}`);
262	  return policy;
263	};
264	
265	/**
266	 * A claim both reports a payout and draws down the policy's cap, so settling one
267	 * yields the settled policy rather than mutating it: successive claims against
268	 * the same policy are then an explicit chain, not a hidden shared-state effect.
269	 */
270	const claim = (
271	  step: ClaimStep,
272	  policy: Policy,
273	): { result: StepResult; policy: Policy } => {
274	  const charges = chargesFor(step.incident.damages, policy.items);
275	  const reimbursementBeforeCap = sumOf(charges, deductedReimbursementFor);
276	  const payout = roundDownToWholeG(Math.min(reimbursementBeforeCap, policy.remainingCap));
277	  const remainingCap = policy.remainingCap - payout;
278	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
